/**
 * Test the variance of data with an extreme condition number.
 * The condition number is defined in Chan, Golub and Levesque (1983)
 * (American Statistician, 37, 242-247) as:
 * <pre>
 * k = sqrt(1 + mean^2 * N/S) = sqrt(1 + mean^2 / var)   (Eq 2.1)
 * </pre>
 * <p>where N is the number of samples, S is the sum-of-squared deviations from
 * the mean and var is the biased variance.
 *
 * <p>This test exists to demonstrate that the dual-pass with correction is more
 * accurate that the dual-pass algorithm. This can generate a different variance
 * for extreme data to other libraries that do not use the algorithm.
 */
@Test
void testBadlyConditionedData() {
    // This data has a variance of 1.4273452003842682e-29 in: Python numpy; Matlab; R.
    // The 'unlimited' precision result is 1.4262886902433472E-29.
    // This is different by a relative error of ~7.4e-4.
    // Condition number k ~ 3e14. This is very badly conditioned data.
    // 1.00000000000001 is 45 ULP above 1.0.
    final double[] values = { 1, 1, 1, 1, 1, 1, 1.00000000000001 };
    final double dualpassResult = 1.4273452003842682e-29;
    final double correctedDualpassResult = 1.4262886902433472E-29;
    final double v = Variance.of(values).getAsDouble();
    Assertions.assertNotEquals(dualpassResult, v, "Dual-pass result");
    Assertions.assertEquals(correctedDualpassResult, v, "Corrected dual-pass result");
    // Check using the helper function
    Assertions.assertEquals(computeExpectedVariance(values, null), v, "Reference expected result");
    // Using 256 decimal digits of precision
    final MathContext mc = new MathContext(256);
    final BigDecimal mean = Arrays.stream(values).mapToObj(BigDecimal::new).reduce(BigDecimal.ZERO, BigDecimal::add).divide(BigDecimal.valueOf(values.length), mc);
    final double var = Arrays.stream(values).mapToObj(BigDecimal::new).map(x -> x.subtract(mean)).map(x -> x.pow(2)).reduce(BigDecimal.ZERO, BigDecimal::add).divide(BigDecimal.valueOf(values.length - 1), mc).doubleValue();
    Assertions.assertEquals(var, v, "256-digit precision result");
}

/**
 * Various tests related to MATH-699.
 */
@Test
void testContinuous() {
    final double x0 = 0.0;
    final double x1 = 1.0;
    final double x2 = 2.0;
    final double x3 = 3.0;
    final double p12 = 0.5;
    final AbstractContinuousDistribution distribution;
    distribution = new AbstractContinuousDistribution() {

        @Override
        public double cumulativeProbability(final double x) {
            if (x < x0 || x > x3) {
                throw new DistributionException(DistributionException.OUT_OF_RANGE, x, x0, x3);
            }
            if (x <= x1) {
                return p12 * (x - x0) / (x1 - x0);
            } else if (x <= x2) {
                return p12;
            } else if (x <= x3) {
                return p12 + (1.0 - p12) * (x - x2) / (x3 - x2);
            }
            return 0.0;
        }

        @Override
        public double density(final double x) {
            if (x < x0 || x > x3) {
                throw new DistributionException(DistributionException.OUT_OF_RANGE, x, x0, x3);
            }
            if (x <= x1) {
                return p12 / (x1 - x0);
            } else if (x <= x2) {
                return 0.0;
            } else if (x <= x3) {
                return (1.0 - p12) / (x3 - x2);
            }
            return 0.0;
        }

        @Override
        public double getMean() {
            return ((x0 + x1) * p12 + (x2 + x3) * (1.0 - p12)) / 2.0;
        }

        @Override
        public double getVariance() {
            final double meanX = getMean();
            final double meanX2;
            meanX2 = ((x0 * x0 + x0 * x1 + x1 * x1) * p12 + (x2 * x2 + x2 * x3 + x3 * x3) * (1.0 - p12)) / 3.0;
            return meanX2 - meanX * meanX;
        }

        @Override
        public double getSupportLowerBound() {
            return x0;
        }

        @Override
        public double getSupportUpperBound() {
            return x3;
        }

        @Override
        boolean isSupportConnected() {
            // This is deliberately false; the functionality is the subject of this test
            return false;
        }
    };
    // CDF is continuous before x1 and after x2. Plateau in between:
    // CDF(x1 <= X <= x2) = p12.
    // The inverse returns the infimum.
    double expected = x1;
    double actual = distribution.inverseCumulativeProbability(p12);
    Assertions.assertEquals(expected, actual, 1e-8, "Inverse CDF");
    actual = distribution.inverseSurvivalProbability(1 - p12);
    Assertions.assertEquals(expected, actual, 1e-8, "Inverse SF");
    // Test the continuous region
    expected = 0.5 * (x1 - x0);
    actual = distribution.inverseCumulativeProbability(p12 * 0.5);
    Assertions.assertEquals(expected, actual, 1e-8, "Inverse CDF");
    actual = distribution.inverseSurvivalProbability(1 - p12 * 0.5);
    Assertions.assertEquals(expected, actual, 1e-8, "Inverse SF");
    // Edge case where the result is within the solver accuracy of the lower bound
    expected = x0;
    actual = distribution.inverseCumulativeProbability(Double.MIN_VALUE);
    Assertions.assertEquals(expected, actual, 1e-8, "Inverse CDF");
    actual = distribution.inverseSurvivalProbability(Math.nextDown(1.0));
    Assertions.assertEquals(expected, actual, 1e-8, "Inverse SF");
}

