    // -expm1(shape * log(scale/x))                ==> 3.33066907387547E-16
    // -expm1(shape * log(scale) - shape * log(x)) ==> 4.440892098500625E-16
    final ParetoDistribution dist = ParetoDistribution.of(scale, 0.75);
    // BigDecimal: 1 - (scale/x).pow(3).sqrt().sqrt()
