@ParameterizedTest
@MethodSource
void testMannWhitneyU(double[] x, double[] y, double statistic, double[] p, double mu, PValueMethod method, boolean correct, double eps) {
    MannWhitneyUTest test = MannWhitneyUTest.withDefaults().withMu(mu).with(method).with(correct ? ContinuityCorrection.ENABLED : ContinuityCorrection.DISABLED);
    final double s = mu == 0 ? MannWhitneyUTest.withDefaults().statistic(x, y) : test.statistic(x, y);
    Assertions.assertEquals(statistic, s, "statistic");
    final boolean hasTies = hasTies(x, y);
    // Note: Assertions are within a try-catch block to allow printing the R command
    int i = 0;
    try {
        for (final AlternativeHypothesis h : AlternativeHypothesis.values()) {
            test = test.with(h);
            // Test the default if possible
            final MannWhitneyUTest.Result r = h == AlternativeHypothesis.TWO_SIDED && mu == 0 && method == PValueMethod.AUTO && correct ? MannWhitneyUTest.withDefaults().test(x, y) : test.test(x, y);
            Assertions.assertEquals(statistic, r.getStatistic(), () -> h + " statistic");
            TestUtils.assertProbability(p[i++], r.getPValue(), eps, () -> h + " p-value");
            Assertions.assertEquals(hasTies, r.hasTiedValues(), () -> " tied values");
            // Check symmetry: must reverse sign of mu
            final double other = (long) x.length * y.length - statistic;
            Assertions.assertEquals(other, test.withMu(-mu).statistic(y, x), () -> h + " statistic (y, x)");
        }
    } catch (final AssertionError e) {
        // print failing cases
        TestUtils.printf("x=c%s;%ny=c%s;%nwilcox.test(x, y, exact=%s, correct=%s, alternative='%c', mu=%s)%n", Arrays.toString(x).replace('[', '(').replace(']', ')'), Arrays.toString(y).replace('[', '(').replace(']', ')'), PValueMethod.EXACT == method ? "TRUE" : "FALSE", correct ? "TRUE" : "FALSE", Character.toLowerCase(AlternativeHypothesis.values()[i - 1].toString().charAt(0)), mu);
        throw e;
    }
}

