@MethodSource
void testNuisanceParameter(int a, int b, int c, int d, AlternativeHypothesis alternative, Method method, int points, boolean optimize, double[] expected, double[] eps) {
    final int[][] table = { { a, b }, { c, d } };
    final UnconditionedExactTest test = UnconditionedExactTest.withDefaults().with(alternative).with(method).withInitialPoints(points).withOptimize(optimize);
