@ParameterizedTest
@MethodSource
void testWilcoxonSignedRankDifferences(double[] z, double statistic, double[] p, double mu, PValueMethod method, boolean correct, double eps) {
    WilcoxonSignedRankTest test = WilcoxonSignedRankTest.withDefaults().withMu(mu).with(method).with(correct ? ContinuityCorrection.ENABLED : ContinuityCorrection.DISABLED);
    final double s = mu == 0 ? WilcoxonSignedRankTest.withDefaults().statistic(z) : test.statistic(z);
    Assertions.assertEquals(statistic, s, "statistic");
    final boolean hasTies = hasTies(z);
    final boolean hasZeros = hasZeros(z);
    // Note: Assertions are within a try-catch block to allow printing the R command
    int i = 0;
    for (final AlternativeHypothesis h : AlternativeHypothesis.values()) {
        test = test.with(h);
        // Test the default if possible
        final WilcoxonSignedRankTest.Result r = h == AlternativeHypothesis.TWO_SIDED && mu == 0 && method == PValueMethod.AUTO && correct ? WilcoxonSignedRankTest.withDefaults().test(z) : test.test(z);
        Assertions.assertEquals(statistic, r.getStatistic(), () -> h + " statistic");
        TestUtils.assertProbability(p[i++], r.getPValue(), eps, () -> h + " p-value");
        Assertions.assertEquals(hasTies, r.hasTiedValues(), () -> " tied values");
        Assertions.assertEquals(hasZeros, r.hasZeroValues(), () -> " zero values");
    }
}

