@ParameterizedTest
@MethodSource
void testWilcoxonSignedRank(double[] x, double[] y, double statistic, double[] p, double mu, PValueMethod method, boolean correct, double eps) {
    WilcoxonSignedRankTest test = WilcoxonSignedRankTest.withDefaults().withMu(mu).with(method).with(correct ? ContinuityCorrection.ENABLED : ContinuityCorrection.DISABLED);
    final double s = mu == 0 ? WilcoxonSignedRankTest.withDefaults().statistic(x, y) : test.statistic(x, y);
    final boolean hasTies = hasTies(x, y);
    final int zeros = countZeros(x, y);
    // Note: Assertions are within a try-catch block to allow printing the R command
    int i = 0;
    try {
        for (final AlternativeHypothesis h : AlternativeHypothesis.values()) {
            test = test.with(h);
            // Test the default if possible
            final WilcoxonSignedRankTest.Result r = h == AlternativeHypothesis.TWO_SIDED && mu == 0 && method == PValueMethod.AUTO && correct ? WilcoxonSignedRankTest.withDefaults().test(x, y) : test.test(x, y);
            Assertions.assertEquals(statistic, r.getStatistic(), () -> h + " statistic");
            TestUtils.assertProbability(p[i++], r.getPValue(), eps, () -> h + " p-value");
            Assertions.assertEquals(hasTies, r.hasTiedValues(), () -> " tied values");
            Assertions.assertEquals(zeros != 0, r.hasZeroValues(), () -> " zero values");
            // Check symmetry: must reverse sign of mu
            // W+ + W- = n*(n+1)/2 - nZeros
            final double other = (long) x.length * (x.length + 1) / 2 - statistic - zeros;
            Assertions.assertEquals(other, test.withMu(-mu).statistic(y, x), () -> h + " statistic (y, x)");
        }
    } catch (final AssertionError e) {
        // print failing cases
        TestUtils.printf("x=c%s;%ny=c%s;%nwilcox.test(x, y, paired=TRUE, exact=%s, correct=%s, alternative='%c')%n", Arrays.toString(x).replace('[', '(').replace(']', ')'), Arrays.toString(y).replace('[', '(').replace(']', ')'), PValueMethod.EXACT == method ? "TRUE" : "FALSE", correct ? "TRUE" : "FALSE", Character.toLowerCase(AlternativeHypothesis.values()[i - 1].toString().charAt(0)));
        throw e;
    }
}

/**
 * Test with a large sample. This tests the {@code exact} parameter does not
 * trigger an exception when the sample is too large. If this behaviour changes
 * this test can be updated to assert the exception.
 */
@ParameterizedTest
@ValueSource(ints = { 2000, 3000 })
void testBigDataSet(int n) {
    final double[] x = IntStream.range(0, n).asDoubleStream().toArray();
    final double[] y = IntStream.range(0, n).mapToDouble(i -> n - i + 0.5).toArray();
    final WilcoxonSignedRankTest test = WilcoxonSignedRankTest.withDefaults().with(PValueMethod.ASYMPTOTIC);
    final double p = test.test(x, y).getPValue();
    Assertions.assertNotEquals(0, p);
    Assertions.assertEquals(p, test.with(PValueMethod.AUTO).test(x, y).getPValue());
    Assertions.assertEquals(p, test.with(PValueMethod.EXACT).test(x, y).getPValue());
}

/**
 * Test the strategies are correctly configured using the various constructors.
 */
@Test
void testProperties() {
    final TiesStrategy defaultTs = TiesStrategy.AVERAGE;
    final NaNStrategy defaultNs = NaNStrategy.FAILED;
    final IntUnaryOperator randomSource = x -> x;
    NaturalRanking ranking;
    ranking = new NaturalRanking();
    Assertions.assertEquals(defaultTs, ranking.getTiesStrategy());
    Assertions.assertEquals(defaultNs, ranking.getNanStrategy());
    ranking = new NaturalRanking(randomSource);
    Assertions.assertEquals(TiesStrategy.RANDOM, ranking.getTiesStrategy());
    Assertions.assertEquals(defaultNs, ranking.getNanStrategy());
    final TiesStrategy[] ts = TiesStrategy.values();
    final NaNStrategy[] ns = NaNStrategy.values();
    for (final NaNStrategy n : ns) {
        ranking = new NaturalRanking(n);
        Assertions.assertEquals(defaultTs, ranking.getTiesStrategy());
        Assertions.assertEquals(n, ranking.getNanStrategy());
        ranking = new NaturalRanking(n, randomSource);
        Assertions.assertEquals(TiesStrategy.RANDOM, ranking.getTiesStrategy());
        Assertions.assertEquals(n, ranking.getNanStrategy());
        for (final TiesStrategy t : ts) {
            ranking = new NaturalRanking(n, t);
            Assertions.assertEquals(t, ranking.getTiesStrategy());
            Assertions.assertEquals(n, ranking.getNanStrategy());
        }
    }
    for (final TiesStrategy t : ts) {
        ranking = new NaturalRanking(t);
        Assertions.assertEquals(t, ranking.getTiesStrategy());
        Assertions.assertEquals(defaultNs, ranking.getNanStrategy());
    }
}

@Test
void testNullArguments() {
    final TiesStrategy nullTiesStrategy = null;
    final TiesStrategy tiesStrategy = TiesStrategy.AVERAGE;
    final NaNStrategy nullNaNStrategy = null;
    final NaNStrategy nanStrategy = NaNStrategy.FIXED;
    final IntUnaryOperator nullRandomness = null;
    final IntUnaryOperator randomness = x -> x;
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nullTiesStrategy), "ties", "strategy");
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nullNaNStrategy), "nan", "strategy");
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nullNaNStrategy, tiesStrategy), "nan", "strategy");
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nanStrategy, nullTiesStrategy), "ties", "strategy");
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nullRandomness), "random");
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nullNaNStrategy, randomness), "nan", "strategy");
    assertThrowsNPEWithKeywords(() -> new NaturalRanking(nanStrategy, nullRandomness), "random");
}

